const Component = () => {
  const [reverse, setReverse] = useState(true);
  const ref = useCanvas((ctx, { color }) => {
    // 外框顺时针；圆和三角形逆时针时，按非零环绕原则成为镂空
    ctx.beginPath();
    ctx.moveTo(40, 30);
    ctx.lineTo(320, 30);
    ctx.lineTo(320, 250);
    ctx.lineTo(40, 250);
    ctx.closePath();
    ctx.moveTo(190, 140);
    ctx.arc(130, 140, 60, 0, Math.PI * 2, reverse);
    if (reverse) {
      ctx.moveTo(250, 90);
      ctx.lineTo(200, 190);
      ctx.lineTo(300, 190);
    } else {
      ctx.moveTo(250, 90);
      ctx.lineTo(300, 190);
      ctx.lineTo(200, 190);
    }
    ctx.closePath();
    ctx.fillStyle = color("accent");
    ctx.shadowColor = color("overlay");
    ctx.shadowOffsetX = 8;
    ctx.shadowOffsetY = 8;
    ctx.shadowBlur = 10;
    ctx.fill();
  }, [reverse]);

  return (
    <Demo>
      <Stage canvasRef={ref} height={280} />
      <Row>
        <ui.Switch checked={reverse} onCheckedChange={setReverse} label="圆与三角形逆时针绘制（剪纸效果）" />
      </Row>
    </Demo>
  );
};
